cypress_script:
describe('Multi-level dropdown navigation menu', () => {
  it('should display menu items when Downloads is clicked', () => {
    cy.visit('https://the-internet.herokuapp.com/jqueryui/menu');
    cy.get('#menu').contains('Downloads').click();
    cy.get('#menu').should('contain', 'PDF');
    cy.get('#menu').should('contain', 'CSV');
    cy.get('#menu').should('contain', 'Excel');
  });

  it('should not change the URL when clicking on PDF', () => {
    cy.visit('https://the-internet.herokuapp.com/jqueryui/menu');
    cy.get('#menu').contains('Downloads').click();
    cy.get('#menu').contains('PDF').click();
    cy.url().should('eq', 'https://the-internet.herokuapp.com/jqueryui/menu');
    cy.get('#menu').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Multi-level dropdown navigation menu', () => {
  test('should display menu items when Downloads is clicked', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/jqueryui/menu');
    await page.click('#menu >> text=Downloads');
    await expect(page.locator('#menu')).toContainText('PDF');
    await expect(page.locator('#menu')).toContainText('CSV');
    await expect(page.locator('#menu')).toContainText('Excel');
  });

  test('should not change the URL when clicking on PDF', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/jqueryui/menu');
    await page.click('#menu >> text=Downloads');
    await page.click('#menu >> text=PDF');
    await expect(page.url()).toBe('https://the-internet.herokuapp.com/jqueryui/menu');
    await expect(page.locator('#menu')).toBeVisible();
  });
});
